import { describe, expect, it } from "vitest";
import { CallType, FlowNodeType, type SkillBlock } from "../types";
import { skillBlockToGraph } from "./skill-flow-import";

function makeBlock(steps: SkillBlock["steps"]): SkillBlock {
  return { ordered_block_id: "card_replace__main", complete_when: null, steps };
}

describe("skillBlockToGraph", () => {
  it("maps every v2 step kind onto a visible node", () => {
    const block = makeBlock([
      {
        id: "record_reason",
        kind: "autonomous",
        instructions: "Ask what happened to the card.\nMore detail below.",
        next: "collect_target",
      },
      { id: "collect_target", kind: "collect", collect: "replace_target", next: "check" },
      { id: "check", kind: "execute", execute_tool: "eligibility_check", next: "remember" },
      { id: "remember", kind: "set_memory", set_memory: { locked: true }, next: "notify" },
      { id: "notify", kind: "action", action: "utter_done", next: "hand_off" },
      { id: "hand_off", kind: "call", call: "card_disambiguation", next: "leave" },
      { id: "leave", kind: "link", link: "report_fraud" },
      { id: "END", kind: "end" },
    ]);

    const { nodes } = skillBlockToGraph(block, ["card_disambiguation"]);
    const byId = new Map(nodes.map((node) => [node.id, node]));

    expect(byId.get("record_reason")).toMatchObject({
      type: FlowNodeType.Autonomous,
      label: "Ask what happened to the card.",
    });
    expect(byId.get("collect_target")?.type).toBe(FlowNodeType.CollectInformation);
    expect(byId.get("check")).toMatchObject({
      type: FlowNodeType.Call,
      callType: CallType.Tool,
      label: "eligibility_check",
    });
    expect(byId.get("remember")).toMatchObject({
      type: FlowNodeType.SetSlots,
      label: "Set memory",
    });
    expect(byId.get("notify")?.type).toBe(FlowNodeType.Message);
    expect(byId.get("hand_off")).toMatchObject({
      type: FlowNodeType.Call,
      callType: CallType.Flow,
    });
    expect(byId.get("leave")?.type).toBe(FlowNodeType.Link);
    expect(byId.has("END")).toBe(false);
  });

  it("expands route steps into condition nodes carrying their expressions", () => {
    const block = makeBlock([
      {
        id: "route_entry",
        kind: "route",
        noop: true,
        next: [
          { if: "session.card_replace.eligible == False", then: "ineligible" },
          { if: null, then: "proceed" },
        ],
      },
      { id: "ineligible", kind: "action", action: "utter_not_eligible", next: "END" },
      { id: "proceed", kind: "action", action: "utter_proceed", next: "END" },
      { id: "END", kind: "end" },
    ]);

    const { nodes, edges } = skillBlockToGraph(block, []);
    const conditionNodes = nodes.filter((node) => node.type === FlowNodeType.Condition);
    expect(conditionNodes).toHaveLength(2);
    const ifNode = conditionNodes.find((node) => node.label.startsWith("If"));
    expect(ifNode?.label).toBe("If session.card_replace.eligible == False");
    expect(edges.length).toBeGreaterThan(0);
  });

  it("truncates long autonomous instruction labels", () => {
    const longInstruction = "x".repeat(80);
    const block = makeBlock([
      { id: "think", kind: "autonomous", instructions: longInstruction, next: "END" },
      { id: "END", kind: "end" },
    ]);
    const { nodes } = skillBlockToGraph(block, []);
    const label = nodes.find((node) => node.id === "think")?.label ?? "";
    expect(label.length).toBeLessThanOrEqual(60);
    expect(label.endsWith("…")).toBe(true);
  });

  it("degrades unknown step kinds to pass-through instead of crashing", () => {
    const block = makeBlock([
      { id: "mystery", kind: "brand_new_kind", next: "notify" },
      { id: "notify", kind: "action", action: "utter_done", next: "END" },
      { id: "END", kind: "end" },
    ]);
    const { nodes, edges } = skillBlockToGraph(block, []);
    expect(nodes.some((node) => node.id === "notify")).toBe(true);
    // The unknown step is a noop: the start edge passes through to the action.
    expect(edges.some((edge) => edge.targetId === "notify")).toBe(true);
  });

  it("produces a start-only graph for an empty block", () => {
    const { nodes, edges } = skillBlockToGraph(makeBlock([]), []);
    expect(nodes.map((node) => node.type)).toEqual([FlowNodeType.Start]);
    expect(edges).toEqual([]);
  });
});
